def line(x1,y1,x2,y2,c='#33574d',w=3,d=''):return f'<path d="M{x1} {y1}L{x2} {y2}" fill="none" stroke="{c}" stroke-width="{w}" {d}/>'
def rect(x,y,w,h,c='#e7eee4',r=6,stroke='#33574d'):return f'<rect x="{x}" y="{y}" width="{w}" height="{h}" rx="{r}" fill="{c}" stroke="{stroke}" stroke-width="2"/>'
def circle(x,y,r,c='#e7eee4',stroke='#33574d'):return f'<circle cx="{x}" cy="{y}" r="{r}" fill="{c}" stroke="{stroke}" stroke-width="2"/>'
def arrow(x1,y1,x2,y2,c='#5087ac'):return line(x1,y1,x2,y2,c,4,'marker-end="url(#a)"')
def court(x,y,scale=1,c='#e3d3b4'):
 return f'<g transform="translate({x} {y}) scale({scale})"><path d="M0 28L45 0L90 28Z" fill="{c}" stroke="#33574d" stroke-width="3"/>'+rect(0,80,90,9,c,0)+''.join(rect(i,32,10,44,'#fffaf0',0) for i in [9,30,51,72])+line(0,30,90,30)+ '</g>'
