def money(x,y):return rect(x,y,43,22,'#b4d4ac',1)+circle(x+21,y+11,6,'#e7f3dc')
def car(x,y):return f'<path d="M{x} {y+15}l8-15h37l12 15h8v22H-2Z" transform="translate(0 0)" fill="#d4a359" stroke="#33574d" stroke-width="2"/>'+circle(x+12,y+37,7,'#46545a')+circle(x+50,y+37,7,'#46545a')
