 for i,g in enumerate(ps):svg+=f'<g transform="translate({180*i} 0)"><rect width="180" height="180" fill="{["#f7f4e9","#edf4ed","#edf2f6"][i]}"/>'+g+'</g>'
 svg+='</svg>';ap=A/f'{qid}.svg';ap.write_text(svg)
